import type { Href } from 'expo-router';

import type { Macros, NutritionSource } from '@/core/types';

/** Typed-routes are generated by `expo start`; build hrefs from strings so tsc never depends on them. */
export function href(path: string): Href {
  return path as Href;
}

export const routes = {
  home: '/',
  newRecipe: '/recipes/new',
  customFood: '/recipes/foods',
  addPortion: '/recipes/calibrations',
  portion: (id: string) => `/recipes/calibrations?id=${encodeURIComponent(id)}`,
  recipe: (id: string) => `/recipes/${id}`,
  editRecipe: (id: string) => `/recipes/${id}/edit`,
  newBatch: (id: string) => `/recipes/${id}/batch`,
};

export function fmtKcal(n: number): string {
  return `${Math.round(n)} kcal`;
}

export function fmtG(n: number): string {
  const rounded = Math.round(n * 10) / 10;
  return `${Number.isInteger(rounded) ? rounded : rounded.toFixed(1)} g`;
}

export function basisLabel(basis: 'cooked' | 'raw'): string {
  return basis === 'cooked' ? 'per 100 g cooked' : 'per 100 g raw';
}

const SOURCE_LABELS: Record<NutritionSource, string> = {
  usda: 'USDA',
  openfoodfacts: 'Open Food Facts',
  recipe: 'Recipe',
  custom: 'Custom',
  ai_estimate: 'AI estimate',
};

export function sourceLabel(source: NutritionSource): string {
  return SOURCE_LABELS[source];
}

export function macroLine(m: Macros): string {
  return `${Math.round(m.calories)} kcal · ${fmtG(m.protein)} protein`;
}

export function formatDate(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
}

/** Parse a user-typed number ("1,5" and "1.5" both work). Undefined when blank or not a number. */
export function parseNum(text: string | undefined): number | undefined {
  if (text == null) return undefined;
  const t = text.trim().replace(',', '.');
  if (t === '') return undefined;
  const n = Number(t);
  return Number.isFinite(n) ? n : undefined;
}

/** Number → editable text. */
export function numText(n: number | undefined): string {
  if (n == null || !Number.isFinite(n)) return '';
  return String(Math.round(n * 100) / 100);
}
